// Original sign images extracted without modification from Japan's NPA guide,
// Traffic Lights and Road Signs, PDF page 5 (image objects 29 and 30).
// https://www.npa.go.jp/english/bureau/traffic/traffic-light_english.pdf#page=5
// Embed the source images so standalone question SVGs never depend on external
// image requests. The circular viewport removes only the white square corners.
const SIGNS = {
  "no-crossing": {
    "code": "312",
    "width": 244,
    "height": 249,
    "cx": 121.5,
    "cy": 127,
    "cropRadius": 117,
    "image": "data:image/png;base64,"
  },
  "no-uturn": {
    "code": "313",
    "width": 241,
    "height": 243,
    "cx": 123,
    "cy": 122.5,
    "cropRadius": 116.5,
    "image": "data:image/png;base64,"
  }
};

export function vehicleProhibitionSign(type, radius = 42) {
  const sign = SIGNS[type];
  if (!sign) throw new RangeError('Unsupported vehicle prohibition sign: ' + type);
  const { code, width, height, cx, cy, cropRadius, image } = sign;
  const clip = 'official-sign-' + code;
  return `<svg data-official-sign="${code}" x="${-radius}" y="${-radius}" width="${radius * 2}" height="${radius * 2}" viewBox="${cx - cropRadius} ${cy - cropRadius} ${cropRadius * 2} ${cropRadius * 2}"><defs><clipPath id="${clip}"><circle cx="${cx}" cy="${cy}" r="${cropRadius}"/></clipPath></defs><image width="${width}" height="${height}" href="${image}" clip-path="url(#${clip})"/></svg>`;
}
